import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aplicarDuasVezes, transformarLista, compor } from './solution.mjs';

test('aplicarDuasVezes aplica a transformação duas vezes', () => {
  assert.equal(aplicarDuasVezes(3, (n) => n * 2), 12);
  assert.equal(aplicarDuasVezes('oi', (s) => s + '!'), 'oi!!');
});

test('transformarLista devolve nova lista com itens transformados', () => {
  assert.deepEqual(transformarLista([1, 2, 3], (n) => n + 1), [2, 3, 4]);
});

test('transformarLista não altera a lista original', () => {
  const original = [1, 2, 3];
  transformarLista(original, (n) => n * 10);
  assert.deepEqual(original, [1, 2, 3]);
  assert.deepEqual(transformarLista(['a', 'b'], (t) => t.toUpperCase()), ['A', 'B']);
});

test('compor aplica g primeiro e f depois', () => {
  const gritar = compor((s) => s + '!', (s) => s.toUpperCase());
  assert.equal(gritar('oi'), 'OI!');
});

