export function aplicarDuasVezes(valor, transformacao) {
  return transformacao(transformacao(valor));
}

export function transformarLista(lista, transformacao) {
  const resultado = [];
  for (const item of lista) {
    resultado.push(transformacao(item));
  }
  return resultado;
}

export function compor(f, g) {
  return function (valor) {
    return f(g(valor));
  };
}
